import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Create plane geometry with 1.6:1 aspect ratio (512:320)
  const width = 1;
  const height = 1 / 1.6;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Container group
  const group = new THREE.Group();
  group.add(mesh);

  // Apply scene placement
  const position = config.scenePosition || [0, 1, 0.06];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // Add text content
  if (config.textContent) {
    const textStr = typeof config.textContent === 'string'
      ? config.textContent
      : (config.textContent[0]?.text || 'Journal 2');

    const textMesh = ctx.fontAtlas.createTextMesh({
      text: textStr,
      fontSize: 0.34,
      fontWeight: 400,
      fontFamily: 'Lora',
      color: 0x16161d,
    });

    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Animation tracking
  const timelines = [];
  const tweens = [];
  const basePos = { x: position[0], y: position[1], z: position[2] };

  // Event handlers
  const handlers = {
    onPointerEnter: () => {
      tweens.forEach(t => t.kill());
      tweens.length = 0;

      const tween = gsap.to(group.position, {
        y: basePos.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      tweens.push(tween);
    },

    onPointerLeave: () => {
      tweens.forEach(t => t.kill());
      tweens.length = 0;

      const tween = gsap.to(group.position, {
        y: basePos.y,
        duration: 0.7,
        ease: 'power3.out',
      });
      tweens.push(tween);
    },

    onPointerDown: () => {
      tweens.forEach(t => t.kill());
      tweens.length = 0;

      const tl = gsap.timeline();
      tl.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0)
      .to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
      }, 0.12);

      timelines.push(tl);

      if (ctx.eventEmitter) {
        ctx.eventEmitter.emit('hub-journal.select');
      }
    },
  };

  group.userData.handlers = handlers;

  // Apply cinematic primitives
  if (config.cinematicPrimitives?.length) {
    config.cinematicPrimitives.forEach(prim => {
      ctx.primitives?.[prim.name]?.(group, prim.params || {});
    });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    tweens.forEach(t => t.kill());
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
